#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1000000007LL;

long long mod_pow(long long a, long long e) {
    long long res = 1 % MOD;
    a %= MOD;
    while (e) {
        if (e & 1) res = res * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int w, h;
    if (!(cin >> w >> h)) return 0;

    long long W = w + 1;
    long long H = h + 1;
    long long N = W * H % MOD;

    // Total ordered triples of distinct points
    long long total = N * ((N - 1 + MOD) % MOD) % MOD * ((N - 2 + MOD) % MOD) % MOD;

    // Count collinear ordered triples
    // Vertical lines: x = const, each has H points
    long long vertical = W * (H % MOD) % MOD * ((H - 1 + MOD) % MOD) % MOD * ((H - 2 + MOD) % MOD) % MOD;
    // Horizontal lines: y = const, each has W points
    long long horizontal = H * (W % MOD) % MOD * ((W - 1 + MOD) % MOD) % MOD * ((W - 2 + MOD) % MOD) % MOD;

    long long diagonal = 0;
    for (int dx = 1; dx <= w; ++dx) {
        for (int dy = 1; dy <= h; ++dy) {
            if (std::gcd(dx, dy) != 1) continue;
            long long cnt = (long long)(w - dx + 1) * (h - dy + 1) % MOD;
            long long k = std::min(w / dx, h / dy) + 1; // number of points on the line
            if (k >= 3) {
                long long add = cnt * (k % MOD) % MOD * ((k - 1) % MOD) % MOD * ((k - 2) % MOD) % MOD;
                diagonal = (diagonal + add) % MOD;
            }
        }
    }
    diagonal = diagonal * 2 % MOD; // both slopes positive and negative

    long long collinear = (vertical + horizontal + diagonal) % MOD;

    // Non-collinear ordered triples
    long long noncol = (total - collinear + MOD) % MOD;

    // Count triples with odd twice-area (D odd)
    // Parity classes: (x%2, y%2)
    long long cnt[2][2] = {};
    for (int x = 0; x <= w; ++x) {
        for (int y = 0; y <= h; ++y) {
            cnt[x & 1][y & 1]++;
        }
    }

    long long odd = 0;
    // Iterate over all ordered triples of parity classes
    for (int a = 0; a < 4; ++a) {
        int ax = a >> 1, ay = a & 1;
        for (int b = 0; b < 4; ++b) {
            int bx = b >> 1, by = b & 1;
            for (int c = 0; c < 4; ++c) {
                int cx = c >> 1, cy = c & 1;
                // D mod 2 = (bx-ax)*(cy-ay) - (by-ay)*(cx-ax) mod 2
                // In mod 2, subtraction = addition
                int term1 = (bx ^ ax) & (cy ^ ay);
                int term2 = (by ^ ay) & (cx ^ ax);
                int Dmod2 = term1 ^ term2;
                if (Dmod2 == 1) {
                    long long ways = cnt[ax][ay] * cnt[bx][by] % MOD * cnt[cx][cy] % MOD;
                    odd = (odd + ways) % MOD;
                }
            }
        }
    }

    // Answer = (noncol - odd) / 2 mod MOD
    long long inv2 = (MOD + 1) / 2; // 500000004
    long long ans = (noncol - odd + MOD) % MOD;
    ans = ans * inv2 % MOD;

    cout << ans << "\n";
    return 0;
}
